B.am=s([],t.zr)
B.X3=s(["Th..Thank you, Mateo. I..I owe you my life...","The words grow distant as exhaustion pulls you back into darkness."],t.s)
B.Oq=new A.cu("Close your eyes","intro_pass_out_to_spanish_home",!0,!1)
B.YP=s([B.Oq],t.u)
